// named-lock — cross-process named lock
// Backend: shm

fn lock_create::(name) {
    let shm = @shm_create(name + ".lock", 32);
    @shm_write(shm, 0, @bytes(@json_encode({"holder": "", "since": 0})));
    return shm;
}

fn lock_open::(name) { return @shm_open_z(name + ".lock"); }

fn lock_state::(shm) {
    return @json_decode(@mem_to_string(@mem_from_bytes(@shm_read(shm, 0, 32))));
}

fn lock_acquire::(shm, holder) {
    let s = lock_state(shm);
    if (s["holder"] == "") {
        @shm_write(shm, 0, @bytes(@json_encode({"holder": holder, "since": @time_ms()})));
        return true;
    }
    return false;
}

fn lock_release::(shm, holder) {
    let s = lock_state(shm);
    if (s["holder"] != holder) { return false; }
    @shm_write(shm, 0, @bytes(@json_encode({"holder": "", "since": 0})));
    return true;
}

fn lock_held_by::(shm) { return lock_state(shm)["holder"]; }

fn lock_age_ms::(shm) {
    let s = lock_state(shm);
    if (s["holder"] == "") { return 0; }
    return @time_ms() - s["since"];
}

fn lock_force_release::(shm) {
    @shm_write(shm, 0, @bytes(@json_encode({"holder": "", "since": 0})));
    return true;
}

fn version::() { return "1.0.0"; }
